  + '.lb-perg{background:var(--paper,#FBF8F2);border-radius:12px;padding:12px;margin:10px 0}.lb-rot{display:block;font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:#A8455A;margin-bottom:4px}'
  + '.lb-resp{display:flex;gap:6px;flex-wrap:wrap;margin-top:10px}.lb-resp input{font:inherit;flex:1 1 140px;min-width:0;border:1px solid var(--line,#E2E0D8);border-radius:10px;padding:8px 10px}.lb-resp button{font:inherit;font-size:14px;border:0;border-radius:10px;padding:8px 14px;background:#1F5C56;color:#fff;cursor:pointer}.lb-resp button.sec{background:transparent;color:#1F5C56;border:1px solid #1F5C56}'
